export default "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<meta name=\"robots\" content=\"noindex, nofollow\">\n<meta name=\"theme-color\" content=\"#0b1815\">\n<title>Innovation Hub \u00b7 Diaphora Labs</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Archivo:wdth,wght@100..125,400..900&family=Martian+Mono:wght@400;500;600&family=Source+Serif+4:ital,opsz,wght@0,8..60,300..600;1,8..60,400&display=swap\">\n<style>\n:root{\n  --paper:#0b1815;--panel:#123029;--chip:#16382f;--rule:#1e4a3e;\n  --ink:#ece7d9;--muted:#a9b5ac;--faint:#7c9086;\n  --bronze:#b8894a;--site:#d9a865;--current:#cbf51f;\n  --heat:#e0875a;--water:#79b8c4;--green:#9cc5a1;--violet:#c3a0d4;\n  --f-display:\"Archivo\",\"Helvetica Neue\",Arial,sans-serif;\n  --f-body:\"Source Serif 4\",Georgia,\"Times New Roman\",serif;\n  --f-mono:\"Martian Mono\",ui-monospace,\"SFMono-Regular\",Menlo,monospace;\n  color-scheme:dark;\n}\n*{box-sizing:border-box}\nhtml{scroll-behavior:smooth;scrollbar-color:var(--bronze) var(--paper)}\nbody{margin:0;background:var(--paper);color:var(--ink);font:16.5px/1.6 var(--f-body);-webkit-font-smoothing:antialiased}\n::selection{background:var(--current);color:var(--paper)}\na{color:var(--site)}\n.wrap{max-width:1120px;margin:0 auto;padding:28px 16px 64px;display:flex;flex-direction:column;gap:18px}\nheader{padding:12px 0 8px;border-bottom:2px solid var(--bronze)}\n.lockup{display:flex;align-items:center;gap:8px;font:900 11px/1 var(--f-display);font-stretch:125%;letter-spacing:.07em}\n.kicker{font:600 11px/1.4 var(--f-mono);letter-spacing:.16em;text-transform:uppercase;color:var(--bronze);margin:22px 0 8px}\nh1{font:900 clamp(34px,6vw,64px)/.95 var(--f-display);font-stretch:125%;letter-spacing:-.015em;margin:0;text-transform:uppercase}\n.lede{font-size:clamp(17px,2.1vw,20px);line-height:1.5;color:var(--muted);max-width:60ch;margin:16px 0 4px}\n.meta{font:500 11px/1.8 var(--f-mono);letter-spacing:.08em;text-transform:uppercase;color:var(--faint);margin-top:14px}\nnav.jump{position:sticky;top:0;z-index:10;background:var(--paper);border-bottom:1px solid var(--rule);display:flex;gap:6px 16px;flex-wrap:wrap;padding:10px 0}\nnav.jump a{font:600 11px/1.4 var(--f-mono);letter-spacing:.06em;text-transform:uppercase;color:var(--muted);text-decoration:none}\nnav.jump a:hover{color:var(--ink)}\nsection.card{background:var(--panel);border:1px solid var(--rule);border-radius:6px;padding:22px 22px 24px;scroll-margin-top:56px}\n.eyebrow{font:600 11px/1.4 var(--f-mono);letter-spacing:.14em;text-transform:uppercase;color:var(--site);margin-bottom:6px}\nh2{font:800 clamp(22px,3vw,30px)/1.1 var(--f-display);font-stretch:112%;margin:0 0 12px}\nh3{font:700 20px/1.25 var(--f-display);margin:22px 0 8px}\np{margin:0 0 12px}\n.grid2,.grid3,.grid4{display:grid;gap:10px}\n.grid2{grid-template-columns:repeat(2,minmax(0,1fr))}\n.grid3{grid-template-columns:repeat(3,minmax(0,1fr))}\n.grid4{grid-template-columns:repeat(4,minmax(0,1fr))}\n@media (max-width:1000px){.grid4{grid-template-columns:repeat(2,minmax(0,1fr))}.grid3{grid-template-columns:repeat(2,minmax(0,1fr))}}\n@media (max-width:620px){.grid2,.grid3,.grid4{grid-template-columns:minmax(0,1fr)}}\n.tile{background:var(--chip);border-radius:6px;padding:14px 16px;font-size:14px;line-height:1.55}\n.tile b{display:block;font:700 16.5px/1.25 var(--f-display);margin-bottom:5px;color:var(--ink)}\n.tile .n{display:block;font:800 30px/1 var(--f-display);font-variant-numeric:tabular-nums;color:var(--ink);margin-bottom:6px}\n.tile .tag{display:inline-block;font:600 11px/1 var(--f-mono);letter-spacing:.06em;text-transform:uppercase;color:var(--faint);margin-bottom:6px}\n.tile.hl{outline:1px solid var(--site)}\n.split{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}\n@media (max-width:800px){.split{grid-template-columns:minmax(0,1fr)}}\n.split div{border-top:2px solid var(--c,var(--site));padding-top:10px;font-size:14px}\n.split b{display:block;font:700 20px/1.2 var(--f-display);margin-bottom:4px}\n.tablewrap{overflow-x:auto;border:1px solid var(--rule);border-radius:6px;margin:6px 0 4px}\ntable{border-collapse:collapse;width:100%;min-width:720px;font-size:14px}\nth{text-align:left;font:600 11px/1.3 var(--f-mono);letter-spacing:.06em;text-transform:uppercase;color:var(--muted);padding:10px 12px;border-bottom:1px solid var(--rule);background:var(--paper)}\ntd{padding:11px 12px;border-bottom:1px solid var(--rule);vertical-align:top}\ntr:last-child td{border-bottom:0}\ntd:first-child{font:700 16.5px/1.3 var(--f-display)}\ntd small{display:block;font:500 11px/1.5 var(--f-mono);color:var(--faint);margin-top:3px;letter-spacing:.02em}\nol.steps{margin:6px 0 0;padding:0;list-style:none;counter-reset:s;display:flex;flex-direction:column;gap:10px}\nol.steps li{counter-increment:s;display:grid;grid-template-columns:auto 1fr;gap:4px 14px;background:var(--chip);border-radius:6px;padding:12px 14px}\nol.steps li::before{content:counter(s);grid-row:span 2;font:800 24px/1 var(--f-display);color:var(--site);font-variant-numeric:tabular-nums;min-width:22px}\nol.steps b{font:700 16.5px/1.3 var(--f-display)}\nol.steps .when{font:600 11px/1.5 var(--f-mono);letter-spacing:.06em;text-transform:uppercase;color:var(--faint)}\n.stages{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}\n@media (max-width:860px){.stages{grid-template-columns:minmax(0,1fr)}}\n.stages div{background:var(--chip);border-radius:6px;padding:14px 16px;font-size:14px}\n.stages .st{font:600 11px/1.4 var(--f-mono);letter-spacing:.08em;text-transform:uppercase;color:var(--site)}\n.stages b{display:block;font:800 20px/1.15 var(--f-display);margin:4px 0 6px}\n.stages .size{font:600 14px/1.4 var(--f-mono);color:var(--ink);display:block;margin-bottom:6px}\nul.plain{margin:4px 0 12px;padding-left:20px}ul.plain li{margin:4px 0}\n.note{font-size:14px;color:var(--muted)}\n.callout{background:var(--chip);border-radius:6px;padding:14px 16px;font-size:16.5px}\n.callout b{color:var(--ink)}\n.foot{font:500 11px/1.8 var(--f-mono);letter-spacing:.06em;color:var(--faint);text-align:center;margin-top:10px}\n.foot a{color:var(--muted)}\n@media print{nav.jump{display:none}section.card{break-inside:avoid-page}}\n</style>\n</head>\n<body>\n<div class=\"wrap\">\n<header>\n  <div class=\"lockup\"><svg viewBox=\"0 0 24 24\" width=\"16\" height=\"16\" aria-hidden=\"true\"><path d=\"M3 17h9V7h9\" fill=\"none\" stroke=\"#ece7d9\" stroke-width=\"2.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg><span>DIAPHORA LABS</span></div>\n  <div class=\"kicker\">A proposal for the Niagara Falls Rankin Innovation Hub</div>\n  <h1>One front door for Niagara founders</h1>\n  <p class=\"lede\">The Hub has the home, the community, the programs and capital partners in the building. Diaphora Labs brings technical depth, real industrial problems, a regional and cross-border network, and the company flow that turns that capital into a fund. This page sets out what we would do together, where to start, and how a fund could grow out of it.</p>\n  <div class=\"meta\">Private \u00b7 prepared for Dan Bordenave and the Hub team \u00b7 October 2026 \u00b7 for discussion</div>\n</header>\n\n<nav class=\"jump\" aria-label=\"Sections\">\n  <a href=\"#sum\">Summary</a><a href=\"#bioveld\">Why now: Bioveld</a><a href=\"#agri\">AI in agriculture</a><a href=\"#services\">What we offer</a><a href=\"#tech\">Tools</a><a href=\"#network\">Network</a><a href=\"#fund\">The fund</a><a href=\"#start\">Where to start</a><a href=\"#measure\">Measures</a><a href=\"#honest\">What we're not claiming</a>\n</nav>\n\n<section class=\"card\" id=\"sum\" aria-labelledby=\"sumH\">\n  <div class=\"eyebrow\">Summary</div>\n  <h2 id=\"sumH\">Complement the Hub, never compete with it</h2>\n  <p>The Hub already runs Ignite for early-stage founders and Elevate for companies getting ready to scale, with more than 100 member businesses, workspace, coaching, and partners including the City of Niagara Falls, the University of Niagara Falls Canada and Blue Ocean Angels. Diaphora Labs would add the pieces a Hub of this size rarely has in-house:</p>\n  <div class=\"grid4\">\n    <div class=\"tile\"><b>Technical depth</b>AI, software, engineering feasibility and funding know-how, available to members every week.</div>\n    <div class=\"tile\"><b>Real problems</b>Industrial problems from Niagara companies and sites like Bioveld, so founders build against paying needs.</div>\n    <div class=\"tile\"><b>Reach</b>A network from Hamilton to Waterloo and across the border, and Niagara Tech Week as the region's stage.</div>\n    <div class=\"tile hl\"><b>Capital</b>Company flow for the Hub's capital partners, and a staged path from grants to deal-by-deal investment to a dedicated pre-seed vehicle.</div>\n  </div>\n  <h3>How the two fit</h3>\n  <div class=\"split\">\n    <div style=\"--c:var(--site)\"><b>The Hub</b>Space, membership, Ignite and Elevate, coaching, the City and local partners. The front door and the home.</div>\n    <div style=\"--c:var(--green)\"><b>Diaphora Labs</b>Open Mondays, weekly accountability, office hours, problem sprints, AI tooling, events and the network. The technical engine.</div>\n    <div style=\"--c:var(--water)\"><b>Together</b>A pipeline from idea to company to funding, with a real problem and a first customer behind more of the companies that come through it.</div>\n  </div>\n</section>\n\n<section class=\"card\" id=\"bioveld\" aria-labelledby=\"bioH\">\n  <div class=\"eyebrow\">Why now</div>\n  <h2 id=\"bioH\">What the Bioveld work shows, and what it opens for Hub founders</h2>\n  <p>Diaphora Labs has developed a circular-campus concept for BMI Group's Bioveld lands in Thorold, a 600+ acre multimodal industrial complex on the Welland Canal. It is a concept for discussion with BMI, not an agreement. But the way it was built shows what Diaphora brings to the Hub.</p>\n  <div class=\"grid4\">\n    <div class=\"tile\"><span class=\"n\">Days</span>to turn published site plans into a georeferenced site model, with no input from the landowner</div>\n    <div class=\"tile\"><span class=\"n\">40</span>assets and proposals mapped, each with its own specification sheet</div>\n    <div class=\"tile\"><span class=\"n\">37</span>technologies costed, and 27 research papers and patents screened by readiness level</div>\n    <div class=\"tile\"><span class=\"n\">12</span>federal funding programs matched to specific parts of the plan, with dates</div>\n  </div>\n  <h3>What it opens for Hub members</h3>\n  <div class=\"grid3\">\n    <div class=\"tile\"><b>Industrial problems worth solving</b>Heat, steam, power, water, carbon, materials and freight at a working industrial site. These are the problems that turn into contracts, not class projects.</div>\n    <div class=\"tile\"><b>Proposed test ranges</b>Places to prove a product on real industrial assets: waste heat, a 230 kV connection, rail and docks. Proposed, not built, and each depends on the site's owners and tenants.</div>\n    <div class=\"tile\"><b>Potential first customers</b>About 30 tenants and operators across the Thorold hub. None are committed, but each is a conversation a Hub founder could not easily open alone.</div>\n  </div>\n  <h3>Three Niagara places, one network</h3>\n  <div class=\"split\">\n    <div style=\"--c:var(--site)\"><b>Niagara Falls \u00b7 the Hub</b>Where founders start, meet and work. The city front door.</div>\n    <div style=\"--c:var(--heat)\"><b>Thorold \u00b7 Bioveld</b>Where products are proven against industry: heat, steam, grid, carbon, freight. A proposal.</div>\n    <div style=\"--c:var(--water)\"><b>The falls \u00b7 Project: Waterfall</b>Where products are proven against nature: fog, ice, noise, water. A live proposal with Niagara Parks.</div>\n  </div>\n  <p class=\"note\" style=\"margin-top:12px\">Each place gives founders a reason to use the others. The Hub is the one that exists today, which is why it is the right place to start.</p>\n</section>\n\n<section class=\"card\" id=\"services\" aria-labelledby=\"svcH\">\n  <div class=\"eyebrow\">What we offer</div>\n  <h2 id=\"svcH\">Seven services, starting with the weekly rhythm that already runs</h2>\n  <p>Every Monday is already an open day: founders cowork side by side, then meet for an accountability session to review the week's updates, wins and losses, with private office hours as time allows. The proposal is to formalise what already works: a shared Hub program, on the Hub's calendar, open to every member and reported on monthly.</p>\n  <div class=\"tablewrap\"><table>\n    <thead><tr><th style=\"width:21%\">Service</th><th style=\"width:37%\">What it is</th><th>What the Hub gets</th></tr></thead>\n    <tbody>\n      <tr><td>Open Mondays<small>Every Monday \u00b7 already running</small></td><td>An open coworking day. Founders, freelancers, students and anyone building something work side by side, with Francois there through the day.</td><td>A reason for members to be in the building every week, and a low-pressure way in for people who are not members yet.</td></tr>\n      <tr><td>Weekly accountability session<small>Every Monday \u00b7 already running</small></td><td>Each person reviews the week: updates, wins, losses, and what they commit to by next Monday. Commitments are written down and checked the following week.</td><td>Steady, visible progress among members; a natural next step after Elevate that keeps graduates close; progress to report to funders.</td></tr>\n      <tr><td>Private office hours<small>As time allows \u00b7 bookable</small></td><td>One-to-one time on what is blocking someone: AI and software, technical feasibility, funding (IRAP, SR&amp;ED, Mitacs, FedDev), cross-border questions and approvals.</td><td>Expert time members would otherwise pay for, and a record of what members are stuck on, which shapes the programs.</td></tr>\n      <tr><td>Events<small>Monthly \u00b7 co-branded</small></td><td>Problem nights where industry presents real problems, technical workshops (AI agents for small businesses, funding stacks, selling into the US), and demo nights.</td><td>A steady calendar with new audiences: engineers, industry and investors who would not come to a general business event.</td></tr>\n      <tr><td>Niagara Tech Week<small>27 Sep \u2013 1 Oct 2027 \u00b7 proposed</small></td><td>A decentralised week of independently hosted events across Niagara, convened by Diaphora Labs, closing the Waterloo\u2013Toronto\u2013Niagara run of tech weeks.</td><td>A founding host role: the Niagara Falls programme, a showcase for Hub members, and the Hub's name on the region's biggest tech week from year one.</td></tr>\n      <tr><td>Co-promotion<small>Ongoing</small></td><td>Shared calendar, cross-listed events, newsletter and social swaps, joint announcements to the Diaphora, Delta 0 and Niagara Tech Week audiences.</td><td>Reach beyond the Hub's existing community, especially technical founders and the cross-border audience.</td></tr>\n      <tr><td>Problem sprints<small>12 weeks \u00b7 sponsor-funded</small></td><td>A company pays to have a defined problem worked on by a paid, mixed team for twelve weeks; the deliverable is a decision, with a prototype where it fits. Hub members and students can be on the teams.</td><td>Paid work for members, sponsors as new Hub relationships, and spinouts that start with a first customer.</td></tr>\n    </tbody>\n  </table></div>\n  <p class=\"note\">Terms for each service are in a separate note, to agree together.</p>\n</section>\n\n<section class=\"card\" id=\"agri\" aria-labelledby=\"agriH\">\n  <div class=\"eyebrow\">The first program \u00b7 pending grant approval</div>\n  <h2 id=\"agriH\">AI in the Agriculture Sector \u2014 Niagara</h2>\n  <p>An AI adoption program for Niagara's farms, agri-food businesses and agri-tourism operators, run by the Hub with Francois of Diaphora Labs as Head Coach. Ten businesses, thirty-six weeks, every week: a group session to learn, and an hour of one-to-one coaching to put it to work in their own operation. It starts only if the grant is approved.</p>\n  <div class=\"grid4\">\n    <div class=\"tile\"><span class=\"n\">10</span>participating farm, agri-food and agri-tourism businesses</div>\n    <div class=\"tile\"><span class=\"n\">36</span>weeks, with a group session and one-to-one coaching every week</div>\n    <div class=\"tile\"><span class=\"n\">360</span>hours of one-to-one coaching, about an hour per business per week</div>\n    <div class=\"tile\"><span class=\"n\">1</span>curriculum the Hub keeps and can run again</div>\n  </div>\n  <h3>How it runs</h3>\n  <ol class=\"steps\">\n    <li><b>Needs assessment</b><span class=\"when\">Start</span>Intake interviews and an AI-readiness check for each business, so coaching starts from real operations rather than a generic course.</li>\n    <li><b>A 36-week curriculum built for the sector</b><span class=\"when\">Throughout</span>Weekly modules, session plans and facilitator guides, built on practical uses: crop and yield records, inventory and supply planning, marketing and bookings for agri-tourism, customer service, and grant and admin paperwork. Participants keep the templates, prompt libraries and tool walkthroughs.</li>\n    <li><b>Weekly group sessions</b><span class=\"when\">2 hours a week</span>Led by a program facilitator using the curriculum.</li>\n    <li><b>Weekly one-to-one coaching</b><span class=\"when\">1 hour per business per week</span>Each business picks, sets up and adopts AI tools in its own operation, with the Head Coach alongside.</li>\n    <li><b>Progress tracking and reporting</b><span class=\"when\">Mid-point and end</span>A tracker of each business's adoption milestones, and mid-point and final summaries for the funder.</li>\n  </ol>\n  <h3>Why it matters beyond the program</h3>\n  <div class=\"grid3\">\n    <div class=\"tile\"><b>A template for every sector</b>The same needs-assessment, curriculum and coaching model can run next for tourism and hospitality, manufacturing or construction, under the Hub's name.</div>\n    <div class=\"tile\"><b>Problems for the pipeline</b>What ten agricultural businesses struggle with becomes problem-night material and sprint briefs, and some of it becomes companies.</div>\n    <div class=\"tile\"><b>Links to Bioveld</b>Agriculture runs through the Bioveld concept too: a heated greenhouse, biocarbon for soil and water, and local food for the town. Program alumni are natural pilot partners.</div>\n  </div>\n</section>\n<section class=\"card\" id=\"tech\" aria-labelledby=\"techH\">\n  <div class=\"eyebrow\">Tools</div>\n  <h2 id=\"techH\">The tools behind the work, available to Hub members</h2>\n  <div class=\"grid3\">\n    <div class=\"tile\"><span class=\"tag\">Evora \u00b7 agent tooling</span><b>Does the specialist work a small team can't</b>Reads standards and regulations and cites the clause, searches patents and prior art, builds costing models and bills of materials, and drafts the write-up for the team to correct. It is why a sprint can cost a fraction of a consultancy. People lead and decide; some things are never automated: committing money, signing off a deliverable, or any claim about a named person or company.</div>\n    <div class=\"tile\"><span class=\"tag\">Everdelta \u00b7 approvals research (beta)</span><b>Makes municipal approvals less of a guess</b>Reads a city's past decisions (variances, staff reports, council minutes) to find precedents, check a project against the code and draft a planner-grade write-up. Useful for members opening a storefront, converting a building or developing property. Every output is reviewed by a person, and any work for a municipality is kept separate from work for applicants.</div>\n    <div class=\"tile\"><span class=\"tag\">Delta 0 \u00b7 open source</span><b>Self-serve tools and community, free</b>Diaphora's open, global, self-service incubation tools and wiki, largely agent-run. Every Hub member can use them from day one, with no application.</div>\n  </div>\n  <h3>Funding and credits, in one place</h3>\n  <p>Members get help assembling the stack that fits them: NRC IRAP, SR&amp;ED, Mitacs interns, FedDev Ontario, Intellectual Property Ontario, the federal AI Compute Access Fund, and the cloud credits that are only issued through accredited incubators (AWS Activate, NVIDIA Inception, Microsoft and Google for Startups). Applying for those accreditations jointly means Hub members, not just Diaphora's, can receive them.</p>\n  <p class=\"note\">Applications are never billed as a share of money won.</p>\n</section>\n\n<section class=\"card\" id=\"network\" aria-labelledby=\"netH\">\n  <div class=\"eyebrow\">Network</div>\n  <h2 id=\"netH\">Where Hub founders can go next</h2>\n  <p>Diaphora Labs has relationships across the region's innovation network. None of these organisations competes with the Hub; each is a place a Hub founder can be introduced to at the right stage.</p>\n  <div class=\"tablewrap\"><table>\n    <thead><tr><th style=\"width:24%\">Organisation</th><th style=\"width:34%\">What it is</th><th>What it adds for Hub founders</th></tr></thead>\n    <tbody>\n      <tr><td>Brock University<small>St. Catharines \u00b7 Brock LINC, Goodman, BioLinc</small></td><td>The region's university and its innovation centre.</td><td>Research partners, Mitacs-funded students, lab access, and an academic anchor for Niagara Tech Week.</td></tr>\n      <tr><td>Niagara University<small>Lewiston, New York</small></td><td>A university across the border.</td><td>A US-side academic partner for cross-border pilots, talent and programming.</td></tr>\n      <tr><td>Innovation Factory<small>Hamilton</small></td><td>Hamilton's regional innovation centre.</td><td>Golden Horseshoe programs, advisors and customers one hour away.</td></tr>\n      <tr><td>The Forge<small>Hamilton</small></td><td>McMaster University's startup incubator.</td><td>Peer founders, McMaster talent and a next step for companies that outgrow local programs.</td></tr>\n      <tr><td>Velocity<small>Waterloo</small></td><td>The University of Waterloo's incubator.</td><td>A graduation path for hardware and software companies that need Waterloo's depth.</td></tr>\n      <tr><td>Techstars<small>Global</small></td><td>A global accelerator network.</td><td>A route for the strongest Hub companies into a top-tier accelerator and its investors.</td></tr>\n      <tr><td>Founder Institute<small>Global</small></td><td>A structured pre-seed program run in cities worldwide.</td><td>A proven early-stage curriculum and global mentor network alongside Ignite.</td></tr>\n      <tr><td>The Hub's own partners<small>City of Niagara Falls \u00b7 University of Niagara Falls Canada \u00b7 Blue Ocean Angels</small></td><td>The Hub's existing municipal, academic and investor partners.</td><td>The base everything above builds on, with Blue Ocean Angels and the Niagara Business &amp; Innovation Fund as the natural investors in companies that come through.</td></tr>\n    </tbody>\n  </table></div>\n  <p class=\"note\">Across the border, Buffalo's anchor accelerator is winding down its competition in 2027. That leaves an opening for a cross-border program, and Niagara is the closest place to fill it.</p>\n</section>\n\n<section class=\"card\" id=\"fund\" aria-labelledby=\"fundH\">\n  <div class=\"eyebrow\">Building a fund together</div>\n  <h2 id=\"fundH\">Capital in the order it can actually be raised</h2>\n  <p>Niagara founders run out of options between their first grant and a Toronto seed round. The Hub already sits beside the capital to close that gap: the Niagara Business &amp; Innovation Fund, which invests loan and equity capital in Niagara businesses from the same building, and Blue Ocean Angels. Diaphora Labs would not start a rival fund. It would bring what a fund needs most, a steady flow of companies with real customers, and help build a dedicated early-stage vehicle with these partners, in stages, each one earning the next.</p>\n  <div class=\"stages\">\n    <div><span class=\"st\">Stage 1 \u00b7 now</span><b>Non-dilutive money and credits</b><span class=\"size\">Grants and credits</span>A joint application to FedDev Ontario's Regional Innovation Ecosystem stream, which funds exactly this kind of incubator programming, with the Hub as applicant and Diaphora as delivery partner. Incubator accreditations that turn into cloud credits for members. No equity taken from anyone.</div>\n    <div><span class=\"st\">Stage 2 \u00b7 first companies</span><b>One investment at a time</b><span class=\"size\">\u2248C$150\u2013500k per company</span>Companies from the Hub and from problem sprints presented to the Niagara Business &amp; Innovation Fund and Blue Ocean Angels, deal by deal, with the company's industry sponsor invited to invest alongside. Each deal builds the record a dedicated fund needs.</div>\n    <div><span class=\"st\">Stage 3 \u00b7 after 4\u20136 deals</span><b>A dedicated Niagara pre-seed vehicle</b><span class=\"size\">\u2248C$3\u201310M</span>Built with the Hub's existing capital partners, with an independent investment committee. Investors could include local families and businesses, regional and economic-development partners, and cross-border investors. Because the Hub is a non-profit, equity is held in a separate for-profit vehicle.</div>\n  </div>\n  <h3>Why this fund would be different</h3>\n  <div class=\"callout\"><b>Its companies start with a customer.</b> When a company comes out of a problem sprint, the company that brought the problem is its design partner and likely first customer from day one. Industrial sites like Bioveld add a place to prove the product. That is a genuinely lower-risk kind of pre-seed company, and it is the part investors will find new.</div>\n  <h3>Ground rules from the start</h3>\n  <ul class=\"plain\">\n    <li><b>Separate vehicles.</b> Public money stays with the non-profit Hub and its programs; equity sits only in the for-profit investment vehicle; Diaphora's operating company stays separate from both. One going wrong never takes down the others.</li>\n    <li><b>Independent decisions.</b> Neither the Hub nor Diaphora decides alone on companies it is close to; conflicts are declared and the committee decides.</li>\n    <li><b>Agreed terms before the first success.</b> What the Hub, Diaphora and a sponsor each receive when a company is formed is written into the templates now, not negotiated under pressure later.</li>\n    <li><b>Securities advice before any raise.</b> Each stage is structured with legal advice on who can invest and how.</li>\n  </ul>\n</section>\n\n<section class=\"card\" id=\"start\" aria-labelledby=\"startH\">\n  <div class=\"eyebrow\">Where to start</div>\n  <h2 id=\"startH\">The first 90 days</h2>\n  <ol class=\"steps\">\n    <li><b>Agree a short memorandum of understanding</b><span class=\"when\">October 2026</span>Roles, co-branding, how member data is handled, and how the Hub and Diaphora credit each other. Two pages.</li>\n    <li><b>Formalise Open Mondays as a Hub program</b><span class=\"when\">Already running \u00b7 formalise in November 2026</span>Co-branded and on the Hub's calendar, with the weekly accountability session open to every member and attendance reported monthly. Nothing new has to start, so this is the quickest win on the list.</li>\n    <li><b>Confirm the AI in agriculture grant and recruit the cohort</b><span class=\"when\">On the grant decision</span>Ten farm, agri-food and agri-tourism businesses, intake interviews and readiness checks, then the 36 weeks begin.</li>\n    <li><b>Book the FedDev Ontario call together</b><span class=\"when\">November 2026</span>Continuous intake, so there is no deadline to wait for. The officer conversation shapes the application.</li>\n    <li><b>Invite Elevate graduates into the accountability session</b><span class=\"when\">November 2026</span>So the people the Hub has already invested in keep a weekly rhythm after the program ends.</li>\n    <li><b>Run the first problem night at the Hub</b><span class=\"when\">December 2026</span>Two or three Niagara companies present real problems; founders and students pick them up.</li>\n    <li><b>Apply for incubator accreditations</b><span class=\"when\">December 2026 \u2013 January 2027</span>NVIDIA Inception first, then AWS Activate and the others, so member credits start flowing.</li>\n    <li><b>Announce the Hub as a founding host of Niagara Tech Week</b><span class=\"when\">January 2027</span>With the Niagara Falls programme and a member showcase in the plan from the start.</li>\n  </ol>\n</section>\n\n<section class=\"card\" id=\"measure\" aria-labelledby=\"measH\">\n  <div class=\"eyebrow\">Measures</div>\n  <h2 id=\"measH\">What we would report after 12 months</h2>\n  <div class=\"grid4\">\n    <div class=\"tile\"><b>Open Mondays</b>People coworking each week, how many came back, and what office-hours visitors were stuck on</div>\n    <div class=\"tile\"><b>Accountability</b>Weekly commitments made and kept, and revenue or funding milestones reached by regulars</div>\n    <div class=\"tile\"><b>Funding and adoption</b>Non-dilutive money and credits secured for members, the joint FedDev outcome, and AI tools in daily use at the ten agriculture businesses</div>\n    <div class=\"tile\"><b>Companies</b>Sprints run, people paid, companies formed, and first investments made</div>\n  </div>\n  <p class=\"note\" style=\"margin-top:12px\">Every number is published against its target, including the ones we miss.</p>\n</section>\n\n<section class=\"card\" id=\"honest\" aria-labelledby=\"honH\">\n  <div class=\"eyebrow\">What we're not claiming</div>\n  <h2 id=\"honH\">Where things actually stand</h2>\n  <ul class=\"plain\">\n    <li><b>Bioveld is a concept,</b> prepared for discussion with BMI Group. There is no agreement, and its test ranges are proposals.</li>\n    <li><b>Project: Waterfall is a proposal</b> with Niagara Parks, not a built facility.</li>\n    <li><b>Delta 1, Diaphora's in-person program, is not yet funded,</b> which is one reason a joint application makes sense.</li>\n    <li><b>The AI in agriculture program depends on its grant,</b> and starts only if it is approved.</li>\n    <li><b>No problem sprint has run yet,</b> and the fund has no track record. That is why it starts deal by deal.</li>\n    <li><b>Niagara Tech Week's dates are proposed,</b> with venues not yet booked.</li>\n  </ul>\n</section>\n\n<p class=\"foot\">Francois \u00b7 Diaphora Labs \u00b7 Niagara Falls, Ontario \u00b7 <a href=\"mailto:francois@diaphoralabs.com\">francois@diaphoralabs.com</a> \u00b7 <a href=\"/logout\">Sign out</a></p>\n</div>\n</body>\n</html>\n";
